define(["jquery","core/ajax","core/notification","core/str"],function($,Ajax,Notification,Str){var config={};var init=function(params){config=params;bindEvents()};var bindEvents=function(){$(document).on("click",".btn-fase-action",function(e){e.preventDefault();var btn=$(this);var action=btn.data("action");var faseid=btn.data("faseid");var matrizid=btn.data("matrizid");var cmid=btn.data("cmid");var comentarioField=btn.closest(".fase-actions").find(".fase-comentario");var comentario=comentarioField.val();if(!comentario||!comentario.trim()){Notification.alert("Error","Debe ingresar un comentario para esta acción.","OK");comentarioField.focus();return}var confirmMsg=action==="aprobar"?"¿Está seguro de que desea aprobar esta fase?":"¿Está seguro de que desea rechazar esta fase?";Notification.confirm("Confirmar acción",confirmMsg,"Confirmar","Cancelar",function(){executeAction(faseid,matrizid,cmid,action,comentario)})})};var executeAction=function(faseid,matrizid,cmid,action,comentario){var request=Ajax.call([{methodname:"mod_caracterizacion_fase_action",args:{faseid:faseid,matrizid:matrizid,cmid:cmid,accion:action,comentario:comentario}}]);request[0].done(function(response){if(response.success){Notification.alert("Acción realizada",response.message,"OK").then(function(){window.location.reload();return}).catch(Notification.exception)}else{Notification.alert("Error",response.message,"OK")}}).fail(function(error){Notification.exception(error)})};return{init:init}});